	void ParseAssignmentOperator(ParseNode parent)
	{
		Enter(AssignmentOperator);
		switch (Current.SymbolId)
		{
			case assign:
			case mul_assign:
			case div_assign:
			case mod_assign:
			case add_assign:
			case sub_assign:
			case shl_assign:
			case shr_assign:
			case ushr_assign:
			case and_assign:
			case xor_assign:
			case or_assign:
