	// Expression= AssignmentExpression { comma AssignmentExpression };
	ParseNode ParseExpression()
	{
		Enter(Expression);
		var node = NewNode(Expression);
		node.Add(ParseAssignmentExpression());
		// { comma AssignmentExpression }
		while (Current.SymbolId == comma)
		{
			Consume(node);
			node.Add(ParseAssignmentExpression());
		}
		Leave();
		return node;
	}

